<?php
declare(strict_types=1);require __DIR__.'/../config.php';require_login('admin');$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM exams WHERE id=?');$s->execute([$id]);$exam=$s->fetch();if(!$exam)exit('Ujian tidak ditemukan.');$s=db()->prepare('SELECT * FROM questions WHERE exam_id=? ORDER BY sort_order,id');$s->execute([$id]);$questions=$s->fetchAll();$letters=['A','B','C','D','E','F','G','H'];function imgurl($p){return $p?'../'.ltrim(str_replace('\\','/',$p),'/'):'';}?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Preview</title><style>body{margin:0;background:#f4f7fb;font-family:Arial;color:#17202a}.top{background:#101828;color:#fff;padding:16px 4%;font-weight:bold}.wrap{max-width:980px;margin:auto;padding:20px}.q{background:#fff;border:1px solid #e4e7ec;border-radius:16px;padding:22px;margin:14px 0}.head{display:flex;justify-content:space-between}.badge{background:#ecfdf3;color:#027a48;padding:5px 9px;border-radius:99px;font-size:12px;font-weight:bold}.question{font-size:18px;line-height:1.6;margin:15px 0}.option{border:1px solid #e4e7ec;border-radius:10px;padding:12px;margin:8px 0}.matrix{width:100%;border-collapse:collapse}.matrix th,.matrix td{padding:10px;border-bottom:1px solid #e4e7ec;text-align:center}.matrix th:first-child{text-align:left}.nav{display:flex;justify-content:center;gap:10px;margin:18px}.btn{padding:10px 14px;border:0;border-radius:8px;background:#175cd3;color:white;font-weight:bold}.back{color:#fff;float:right;text-decoration:none}.img{max-width:100%;max-height:450px;display:block;margin:12px auto}</style></head><body><div class="top">Ujian Online · Preview <a class="back" href="questions.php?id=<?=$id?>">← Kembali</a></div><div class="wrap"><h1><?=htmlspecialchars($exam['title'])?></h1><p><?=count($questions)?> soal · Mode <?=($exam['question_mode']??'all')==='one_by_one'?'satu per satu':'semua soal'?></p><div style="background:#eef4ff;padding:12px;border-radius:10px">Mode Preview Admin. Timer dan pengiriman jawaban tidak dijalankan.</div><?php foreach($questions as $i=>$q):$isMatrix=$q['type']==='matrix_disc';?><article class="q"><div class="head"><b>SOAL <?=$i+1?> <span class="badge"><?=$isMatrix?'Matriks / DISC':($q['type']==='essay'?'Essay':'Pilihan Ganda')?></span></b><?php if(!$isMatrix&&($q['use_answer_key']??1)):?><b><?=$q['points']?> poin</b><?php endif;?></div><div class="question"><?=nl2br(htmlspecialchars($q['question_text']))?></div><?php if($q['question_image']??''):?><img class="img" src="<?=htmlspecialchars(imgurl($q['question_image']))?>"><?php endif;?><?php if($q['type']==='essay'):?><div class="option">Jawaban peserta: Essay</div><?php else:$opts=[];foreach($letters as $k){$v=trim((string)($q['option_'.strtolower($k)]??''));if($v!=='')$opts[$k]=$v;}if($isMatrix):?><div><?php foreach($opts as $k=>$v):?><p><b><?=$k?>.</b> <?=htmlspecialchars($v)?></p><?php endforeach;?></div><table class="matrix"><thead><tr><th></th><?php foreach(array_keys($opts) as $k):?><th><?=$k?></th><?php endforeach;?></tr></thead><tbody><tr><th>MIRIP</th><?php foreach($opts as $_):?><td>○</td><?php endforeach;?></tr><tr><th>TIDAK MIRIP</th><?php foreach($opts as $_):?><td>○</td><?php endforeach;?></tr></tbody></table><?php else:foreach($opts as $k=>$v):?><div class="option"><b><?=$k?>.</b> <?=htmlspecialchars($v)?></div><?php endforeach;if(($q['use_answer_key']??1)&&$q['correct_option']):?><small>Kunci admin: <?=htmlspecialchars($q['correct_option'])?></small><?php endif;endif;endif;?></article><?php endforeach;?><div id="nav" class="nav"></div></div><script>const qs=[...document.querySelectorAll('.q')],one=<?=json_encode(($exam['question_mode']??'all')==='one_by_one')?>;if(one&&qs.length){let i=0;function r(){qs.forEach((q,n)=>q.style.display=n===i?'':'none');nav.innerHTML=`<button class="btn" ${i?'':'disabled'} onclick="i--;r()">← Sebelumnya</button><b>Soal ${i+1} / ${qs.length}</b><button class="btn" ${i===qs.length-1?'disabled':''} onclick="i++;r()">Berikutnya →</button>`}r()}</script></body></html>